WITH lines AS (SELECT id, created_at, coupon_codes, pos, rec.product_id, rec.price, rec.promo FROM carts LATERAL VIEW POSEXPLODE(items) e AS pos, rec) SELECT promo, COUNT(*) FILTER (WHERE promo = 'VIP') AS vip_rows, MIN(created_at) AS first_created_at, COUNT_IF(promo = 'SPRING10') AS spring10_events, COUNT_IF(promo = 'WELCOME5') AS welcome5_events, SUM(CASE WHEN promo = 'SPRING10' THEN pos ELSE 0 END) AS spring10_pos FROM lines GROUP BY promo HAVING spring10_events > 1 ORDER BY vip_rows NULLS FIRST
